-- =============================================================
-- 三、自检（只读）
-- =============================================================
SELECT 1 AS ord, '图片总数（期望 40）' AS item, COUNT(*) AS actual FROM attachment WHERE content_type = 'image/jpeg'
UNION ALL SELECT 2, '已入库字节的图片数（期望 40）', COUNT(*) FROM attachment WHERE file_data IS NOT NULL
UNION ALL SELECT 3, '缺 sha256 的图片数（期望 0）', COUNT(*) FROM attachment WHERE file_data IS NOT NULL AND sha256 IS NULL
UNION ALL SELECT 4, '二进制总字节数（期望 7,xxx,xxx）', COALESCE(SUM(octet_length(file_data)), 0) FROM attachment
UNION ALL SELECT 5, '逐图 sha256 与 octet_length 明细', COUNT(*) FROM attachment WHERE file_data IS NOT NULL
ORDER BY ord;

-- 明细：每张图的文件名 / 字节数 / sha256 前 12 位
SELECT id, file_name, octet_length(file_data) AS bytes, left(sha256, 12) AS sha256_head
  FROM attachment
 WHERE file_data IS NOT NULL
 ORDER BY id;
